pragma solidity >=0.8.0;

contract EnvProbe {
    uint256 public numberSeen;
    bytes32 public hashSeen;

    event Snapshot(uint256 number, bytes32 prevHash);

    function snapshot() public {
        uint256 n = block.number;
        numberSeen = n;
        hashSeen = blockhash(n - 1);
        emit Snapshot(n, hashSeen);
    }

    function getNumber() public view returns (uint256) {
        return block.number;
    }

    function getPrevHash() public view returns (bytes32) {
        return blockhash(block.number - 1);
    }

    function hashOf(uint256 n) public view returns (bytes32) {
        return blockhash(n);
    }
}
